import type { PendingAction } from "./pending.ts";

// Builds apps/desktop/PENDING.md: what the interface offers that has no logic yet, grouped by roadmap sprint.
export function pendingReport(actions: readonly PendingAction[], unbuilt: readonly string[]): string {
  const lines = [
    "# Pending",
    "",
    "Generated by `pnpm -F desktop gen:pending` from the `pending(...)` declarations in the ports and the catalog. Do not edit by hand.",
    "",
    "Every action below is reachable in the interface and shows *Not available yet* until its sprint (see `docs/plans/roadmap.md`) plugs in the engine implementation. The prototype (`pnpm prototype`) runs them on sample data.",
    "",
  ];
  const sprints = [...new Set(actions.map((action) => action.sprint))].sort((a, b) => a - b);
  for (const sprint of sprints) {
    lines.push(`## Sprint ${sprint}`, "", "| Action | What it does | Used in |", "|---|---|---|");
    for (const action of actions.filter((item) => item.sprint === sprint)) {
      lines.push(`| \`${action.key}\` | ${action.summary} | ${action.ids.map((id) => `\`${id}\``).join(", ")} |`);
    }
    lines.push("");
  }
  lines.push("## Screens not built yet", "");
  lines.push(...(unbuilt.length > 0 ? unbuilt.map((id) => `- \`${id}\``) : ["None."]), "");
  return lines.join("\n");
}
